mapper.select:
SELECT title, tags, passive, spells, ally_tips, enemy_tips
FROM hero_profiles
WHERE hero_id = #{heroId}

SELECT c.augment_ids, ROUND(c.win_rate * 100, 1) AS win_rate_pct,
       ROUND(c.pick_rate * 100, 1) AS pick_rate_pct
FROM augment_combos c
WHERE c.hero_id = #{heroId}
ORDER BY c.win_rate DESC
LIMIT #{limit}

choose.when:
SELECT id, name, official_name, en_name, tier, ROUND(win_rate * 100, 1) AS win_rate_pct, ROUND(pick_rate * 100, 1) AS pick_rate_pct, win_rank, version FROM heroes
AND id = #{heroId}
AND (name LIKE CONCAT('%', #{keyword}, '%') OR official_name LIKE CONCAT('%', #{keyword}, '%') OR en_name LIKE CONCAT('%', #{keyword}, '%'))
AND tier = #{tier}
ORDER BY win_rank ASC LIMIT #{limit}

SELECT id, name, tier_name, rarity, description, tooltip FROM augments
(name LIKE CONCAT('%', #{keyword}, '%') OR en_name LIKE CONCAT('%', #{keyword}, '%'))
AND tier_name = #{tier}
ORDER BY id DESCASC LIMIT #{limit}

SELECT id, name, tags, plaintext, description, total_price FROM items
(name LIKE CONCAT('%', #{keyword}, '%') OR en_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY id DESCASC LIMIT #{limit}

SELECT h.name AS hero_name, a.name AS augment_name, a.tier_name, r.win_rank, ROUND(r.win_rate * 100, 1) AS win_rate_pct, ROUND(r.pick_rate * 100, 1) AS pick_rate_pct FROM hero_augment_rank r JOIN heroes h ON r.hero_id = h.id JOIN augments a ON r.augment_id = a.id
AND r.hero_id = #{heroId}
AND (h.name LIKE CONCAT('%', #{keyword}, '%') OR a.name LIKE CONCAT('%', #{keyword}, '%'))
AND a.tier_name = #{tier}
ORDER BY r.win_rank ASC LIMIT #{limit}

SELECT h.name AS hero_name, i.name AS item_name, b.item_id, b.build_index, b.group_index, b.slot, ROUND(b.win_rate * 100, 1) AS win_rate_pct, ROUND(b.pick_rate * 100, 1) AS pick_rate_pct FROM hero_item_build b JOIN heroes h ON b.hero_id = h.id LEFT JOIN items i ON b.item_id = i.id
AND b.hero_id = #{heroId}
AND (h.name LIKE CONCAT('%', #{keyword}, '%') OR i.name LIKE CONCAT('%', #{keyword}, '%') OR CAST(b.item_id AS CHAR) = #{keyword})
ORDER BY b.win_rate DESC LIMIT #{limit}

SELECT h.name AS hero_name, c.augment_ids, ROUND(c.win_rate * 100, 1) AS win_rate_pct, c.win_rank FROM augment_combos c JOIN heroes h ON c.hero_id = h.id
AND c.hero_id = #{heroId}
AND h.name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY c.win_rate DESC LIMIT #{limit}
